/** Earth constants (WGS-84 / EGM-96 values, km and s). */
export const MU = 398600.4418;      // gravitational parameter, km^3/s^2
export const RE = 6378.137;         // equatorial radius, km
export const J2 = 1.08262668e-3;    // second zonal harmonic
export const WE = 7.2921159e-5;     // Earth rotation rate, rad/s
